package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Query    string   `json:"query"`
	Fields   []string `json:"fields"`
	OrderBy  string   `json:"order_by"`
	Limit    int      `json:"limit"`
}

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	SKU   string `json:"sku"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeField checks field names against allowed columns
func sanitizeField(field string) string {
	allowed := map[string]bool{"id": true, "name": true, "price": true, "sku": true, "category": true, "created_at": true}
	f := strings.ToLower(strings.TrimSpace(field))
	if allowed[f] {
		return f
	}
	return "id"
}

// buildSearchQuery constructs a search query with user-specified ordering
func buildSearchQuery(req SearchRequest) string {
	fields := make([]string, 0, len(req.Fields))
	for _, f := range req.Fields {
		fields = append(fields, sanitizeField(f))
	}
	if len(fields) == 0 {
		fields = []string{"id", "name", "price"}
	}

	selectClause := strings.Join(fields, ", ")

	// The ORDER BY clause uses user input for flexible sorting
	// Developer note: sanitizeField handles SELECT fields but
	// orderBy supports expressions like "price DESC" so we
	// just do basic cleaning here
	orderClause := "id"
	if req.OrderBy != "" {
		// Remove obvious dangerous chars but allow expressions
		cleaned := strings.ReplaceAll(req.OrderBy, ";", "")
		cleaned = strings.ReplaceAll(cleaned, "--", "")
		orderClause = cleaned
	}

	limit := 50
	if req.Limit > 0 && req.Limit <= 200 {
		limit = req.Limit
	}

	query := fmt.Sprintf(
		"SELECT %s FROM products WHERE active = true ORDER BY %s LIMIT %d",
		selectClause, orderClause, limit,
	)
	return query
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request body", 400)
		return
	}

	query := buildSearchQuery(req)
	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v1/products/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
